export type Cadence = "once" | "daily" | "weekly";

export interface ScheduledJob {
  id: string;
  name: string;
  /** The time an operator typed into the roster, in their own region. */
  localTime: string;
  /** IANA zone identifier, for example "Europe/Berlin". */
  zone: string;
  cadence: Cadence;
}

export function describe(job: ScheduledJob): string {
  return `${job.name} at ${job.localTime} (${job.zone})`;
}

