import type { ScheduledJob } from "./schedule.js";

export interface PollerDeps {
  due(now: Date): Promise<ScheduledJob[]>;
  enqueue(job: ScheduledJob): Promise<void>;
}

export const TICK_MS = 15_000;

export async function tick(now: Date, deps: PollerDeps): Promise<number> {
  const jobs = await deps.due(now);
  for (const job of jobs) await deps.enqueue(job);
  return jobs.length;
}

