import type { ScheduledJob } from "./schedule.js";

export interface PollerDeps {
  due(nowEpochMs: number): Promise<ScheduledJob[]>;
  enqueue(job: ScheduledJob): Promise<void>;
}

export const TICK_MS = 15_000;

/** Compares absolute instants only; a rendered local time is ambiguous. */
export async function tick(nowEpochMs: number, deps: PollerDeps): Promise<number> {
  const jobs = await deps.due(nowEpochMs);
  for (const job of jobs) await deps.enqueue(job);
  return jobs.length;
}
